package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api")public class AcaoSocialController{private final AcaoSocialService s;private final EvidenciaService e;public AcaoSocialController(AcaoSocialService s,EvidenciaService e){this.s=s;this.e=e;}private boolean admin(Authentication a){return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMINISTRADOR"));}@GetMapping("/acoes")public List<AcaoSocialResponse> listar(Authentication a){return s.listar(admin(a));}@GetMapping("/acoes/{id}")public AcaoSocialResponse buscar(@PathVariable Long id,Authentication a){return s.buscar(id,admin(a));}@PostMapping("/acoes")@PreAuthorize("hasRole('ADMINISTRADOR')")public ResponseEntity<AcaoSocialResponse> criar(@Valid @RequestBody AcaoSocialRequest q){return ResponseEntity.status(201).body(s.criar(q));}@PutMapping("/acoes/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse editar(@PathVariable Long id,@Valid @RequestBody AcaoSocialRequest q){return s.editar(id,q);}@PatchMapping("/acoes/{id}/realizar")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse realizar(@PathVariable Long id){return s.realizar(id);}@PatchMapping("/acoes/{id}/cancelar")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse cancelar(@PathVariable Long id){return s.cancelar(id);}@PutMapping("/acoes/{id}/resultado")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse resultado(@PathVariable Long id,@Valid @RequestBody ResultadoAcaoRequest q){return s.resultado(id,q);}@PostMapping("/acoes/{id}/campanhas/{cid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse campanha(@PathVariable Long id,@PathVariable Long cid){return s.vincularCampanha(id,cid);}@DeleteMapping("/acoes/{id}/campanhas/{cid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse removerCampanha(@PathVariable Long id,@PathVariable Long cid){return s.desvincularCampanha(id,cid);}@PostMapping("/acoes/{id}/necessidades/{nid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse necessidade(@PathVariable Long id,@PathVariable Long nid){return s.vincularNecessidade(id,nid);}@DeleteMapping("/acoes/{id}/necessidades/{nid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse removerNecessidade(@PathVariable Long id,@PathVariable Long nid){return s.desvincularNecessidade(id,nid);}@GetMapping("/participacoes")@PreAuthorize("hasRole('ADMINISTRADOR')")public List<ParticipacaoResponse> participacoes(){return s.listarParticipacoes();}@PostMapping("/acoes/{id}/participacoes/{pid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse participacao(@PathVariable Long id,@PathVariable Long pid){return s.vincularParticipacao(id,pid);}@DeleteMapping("/acoes/{id}/participacoes/{pid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public AcaoSocialResponse removerParticipacao(@PathVariable Long id,@PathVariable Long pid){return s.desvincularParticipacao(id,pid);}@PostMapping(value="/acoes/{id}/evidencias",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@PreAuthorize("hasRole('ADMINISTRADOR')")public EvidenciaResponse upload(@PathVariable Long id,@RequestPart("arquivo")MultipartFile f){return e.enviar(id,f);}@PatchMapping("/evidencias/{id}/visibilidade")@PreAuthorize("hasRole('ADMINISTRADOR')")public EvidenciaResponse visibilidade(@PathVariable Long id){return e.visibilidade(id);}@DeleteMapping("/evidencias/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public ResponseEntity<Void> excluirEvidencia(@PathVariable Long id){e.excluir(id);return ResponseEntity.noContent().build();}}
